def transform(g):
    H=len(g); out=[[0]*7 for _ in range(H)]
    c5=next(c for r in range(H) for c in range(len(g[0])) if g[r][c]==5)-8
    out[0][c5]=5
    blocks=[]; r=0
    while r<H:
        if any(g[r][c] for c in range(7)):
            r2=r
            while r2<H and any(g[r2][c] for c in range(7)): r2+=1
            blocks.append((r,r2)); r=r2
        else: r+=1
    def cls(b0,b1,c0):
        return next(x for row in [[g[b0+i][c0+j] for j in range(3)] for i in range(b1-b0)] for x in row if x)
    lefts=[cls(b0,b1,0) for b0,b1 in blocks]; rights=[cls(b0,b1,4) for b0,b1 in blocks]
    spec={1:('R',3),2:('L',2),3:('L',4),6:('D',2)}
    r,c=0,c5
    for v in lefts+rights:
        d,l=spec[v]; r+=1
        if d=='R':
            for i in range(l): out[r][c+i]=v
            c+=l-1
        elif d=='L':
            for i in range(l): out[r][c-i]=v
            c-=l-1
        else:
            for i in range(l): out[r+i][c]=v
            r+=l-1
    return out
